package dev.hackuniversity.roombook.config;

import com.mongodb.ConnectionString;
import com.mongodb.client.MongoClient;
import com.mongodb.client.MongoDatabase;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;

@Configuration
public class MongoConfig {

  @Bean
  MongoDatabase mongoDatabase(MongoClient client, @Value("${spring.mongodb.uri}") String uri) {
    return client.getDatabase(new ConnectionString(uri).getDatabase());
  }
}

public record FeedbackDoc(
    @BsonId ObjectId id,
    long bookingId,
    long roomId,
    Long userId,
    int rating,
    String comment,
    List<String> tags,
    Instant createdAt) {}

@Repository
public class FeedbackRepository {
  private final MongoCollection<FeedbackDoc> feedback;

  public FeedbackRepository(MongoDatabase db) {
    this.feedback = db.getCollection("room_feedback", FeedbackDoc.class);
  }

  public void create(FeedbackDoc doc) {
    try {
      feedback.insertOne(doc);
    } catch (MongoWriteException e) {
      if (e.getError().getCategory() == ErrorCategory.DUPLICATE_KEY) {
        throw new ConflictException("feedback-exists", "This booking already has feedback.", e);
      }
      throw e;
    }
  }

  public List<FeedbackDoc> listForRoom(long roomId, int limit) {
    return feedback.find(eq("roomId", roomId))
        .projection(exclude("userId"))
        .sort(descending("createdAt"))
        .limit(limit)
        .into(new ArrayList<>());
  }

  public boolean editComment(long bookingId, String comment) {
    return feedback.updateOne(eq("bookingId", bookingId), set("comment", comment))
        .getMatchedCount() == 1;
  }

  public boolean addTag(long bookingId, String tag) {
    return feedback.updateOne(eq("bookingId", bookingId), push("tags", tag))
        .getMatchedCount() == 1;
  }

  public boolean remove(long bookingId) {
    return feedback.deleteOne(eq("bookingId", bookingId)).getDeletedCount() == 1;
  }
}

@Component
class FeedbackIndexes implements ApplicationRunner {
  private final MongoDatabase db;

  FeedbackIndexes(MongoDatabase db) {
    this.db = db;
  }

  @Override
  public void run(ApplicationArguments args) {
    var feedback = db.getCollection("room_feedback");
    feedback.createIndex(Indexes.ascending("bookingId"),
        new IndexOptions().unique(true).name("bookingId_unique"));
    feedback.createIndex(
        Indexes.compoundIndex(Indexes.ascending("roomId"), Indexes.descending("createdAt")),
        new IndexOptions().name("room_latest"));
    db.getCollection("activity").createIndex(Indexes.ascending("at"),
        new IndexOptions().expireAfter(90L, TimeUnit.DAYS));
  }
}

@Repository
public class RatingQueries {
  public record RoomRating(long roomId, double average, int count) {}

  private final MongoCollection<FeedbackDoc> feedback;

  public RatingQueries(MongoDatabase db) {
    this.feedback = db.getCollection("room_feedback", FeedbackDoc.class);
  }

  public List<RoomRating> ratingsForRooms(List<Long> roomIds) {
    return feedback.aggregate(List.of(
        match(in("roomId", roomIds)),
        group("$roomId", avg("average", "$rating"), sum("count", 1)),
        sort(descending("average")),
        project(fields(
            excludeId(),
            computed("roomId", "$_id"),
            computed("average", new Document("$round", List.of("$average", 2))),
            include("count")))),
        RoomRating.class).into(new ArrayList<>());
  }
}

@RestController
@RequestMapping("/v1/bookings/{bookingId:\\d{1,18}}/feedback")
class FeedbackController {
  record EditFeedback(@NotNull @Size(max = 2000) String comment) {}

  private final FeedbackRepository feedback;

  FeedbackController(FeedbackRepository feedback) {
    this.feedback = feedback;
  }

  @PatchMapping
  ResponseEntity<Void> edit(@PathVariable long bookingId,
               @Valid @RequestBody EditFeedback body) {
    // Never: updateOne(eq("bookingId", bookingId), new Document("$set", rawBodyMap))
    if (!feedback.editComment(bookingId, body.comment().strip())) {
      throw new NotFoundException("No feedback for booking " + bookingId + ".");
    }
    return ResponseEntity.noContent().build();
  }
}

public void hide(long bookingId, long staffId, String reason) {
  try (ClientSession session = client.startSession()) {
    session.withTransaction(() -> {
      var result = db.getCollection("room_feedback")
          .updateOne(session, eq("bookingId", bookingId), set("hidden", true));
      if (result.getMatchedCount() == 0) {
        throw new NotFoundException("No feedback for booking " + bookingId + ".");
      }
      db.getCollection("moderation_log").insertOne(session, new Document()
          .append("bookingId", bookingId)
          .append("staffId", staffId)
          .append("reason", reason)
          .append("at", clock.instant()));
      return null;
    });
  }
}

@Service
public class FeedbackService {
  private final BookingRepository bookings;
  private final FeedbackRepository feedback;
  private final Clock clock;

  public FeedbackService(BookingRepository bookings, FeedbackRepository feedback, Clock clock) {
    this.bookings = bookings;
    this.feedback = feedback;
    this.clock = clock;
  }

  public void submit(long userId, long bookingId, FeedbackRequest input) {
    Booking booking = bookings.findById(bookingId)
        .filter(b -> b.userId() == userId)
        .orElseThrow(() -> new NotFoundException("No booking with id " + bookingId + "."));
    Instant now = clock.instant();
    if (booking.status() != BookingStatus.CONFIRMED || booking.endsAt().isAfter(now)) {
      throw new ConflictException("feedback-not-open", "Feedback opens when the booking ends.", null);
    }
    feedback.create(new FeedbackDoc(
        new ObjectId(),
        bookingId,
        booking.roomId(),
        userId,
        input.rating(),
        input.comment(),
        input.tags(),
        now));
  }
}

public void run(BsonDocument savedToken) {
  var stream = db.getCollection("room_feedback", FeedbackDoc.class).watch(List.of(
      Aggregates.match(Filters.and(
          Filters.eq("operationType", "insert"),
          Filters.lte("fullDocument.rating", 2)))));
  if (savedToken != null) {
    stream = stream.resumeAfter(savedToken);
  }
  for (var change : stream) {
    notifier.lowRating(change.getFullDocument());
    tokens.save("low-ratings", change.getResumeToken());
  }
}
